const BUDGETS = [199, 299, 499, 999, 1499, 2499, 3999];
const state = { occ: 'joining', budget: 999 };
const rupee = n => '₹' + Math.round(n).toLocaleString('en-IN');
const $ = id => document.getElementById(id);

function chip(label, pressed) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'chip press border-2 border-ink rounded-full px-4 h-10 font-semibold bg-paper';
  b.setAttribute('aria-pressed', pressed ? 'true' : 'false');
  b.textContent = label;
  return b;
}
function renderChips() {
  const o = $('occasions'); o.innerHTML = '';
  Object.entries(OCC).forEach(([k, v]) => { const b = chip(v.label, k === state.occ); b.onclick = () => { state.occ = k; update(); }; o.appendChild(b); });
  const bd = $('budgets'); bd.innerHTML = '';
  BUDGETS.forEach(v => { const b = chip(rupee(v), v === state.budget); b.classList.add('font-mono', 'tnum'); b.onclick = () => { state.budget = v; update(); }; bd.appendChild(b); });
}
function buildKit() {
  const pr = PRINT[$('printPick').value];
  let room = state.budget - DELIVERY_PER_KIT;
  const items = [];
  for (const k of OCC[state.occ].picks) {
    const p = P[k], cost = p.price + pr.per;
    if (cost <= room) { items.push(p); room -= cost; }
  }
  if (!items.length) { const cheapest = OCC[state.occ].picks.map(k => P[k]).sort((a, b) => a.price - b.price)[0]; items.push(cheapest); }
  return { items, pr };
}
function update() {
  renderChips();
  const hc = +$('headcount').value; $('hcOut').textContent = hc; $('rHc').textContent = hc;
  const { items, pr } = buildKit();
  $('kitTitle').textContent = OCC[state.occ].kit;
  $('kitItems').innerHTML = items.map(p => `<li class="flex items-center gap-3 px-5 py-3"><img src="${IMG[p.img]}" alt="" width="48" height="48" loading="lazy" decoding="async" class="h-12 w-12 rounded-xl object-cover border border-line"><span class="flex-1 min-w-0 font-semibold leading-tight">${p.name}</span><span class="font-mono text-xs text-muted">${pr.per ? 'branded' : ''}</span></li>`).join('');
  $('rBudget').textContent = rupee(state.budget);
  $('rPrintName').textContent = $('printPick').selectedOptions[0].textContent;
  $('rDate').textContent = $('needBy').value || 'Tomorrow';
  $('rAddons').textContent = addonVals().length ? addonVals().length + ' selected' : 'None';
  $('waBtn').href = 'https://wa.me/' + WA + '?text=' + encodeURIComponent(quoteText(items, hc));
}
function quoteText(items, hc) {
  const co = $('company').value.trim(), d = $('needBy').value;
  return [`Hi! I need a ${OCC[state.occ].kit.toLowerCase()}${co ? ' for ' + co : ''}. Please share pricing.`, `Headcount: ${hc}`, `Budget per person: ${rupee(state.budget)}`, d ? `Needed by: ${d}` : '', `Branding: ${$('printPick').selectedOptions[0].textContent}`, 'Kit:', ...items.map(p => `- ${p.name}`), addonVals().length ? 'Add-ons: ' + addonVals().join(', ') : ''].filter(Boolean).join('\n');
}
function copy(text, btn, done) {
  const ok = () => { const t = btn.textContent; btn.textContent = done; setTimeout(() => btn.textContent = t, 1600); };
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(ok, ok); else ok();
}

