// upcoming occasions (fixed dates + Diwali)
const OCCASION_DATES = [
  { name: 'Diwali', dates: ['2026-11-08', '2027-10-29'], occ: 'festival', note: 'Hampers & corporate boxes' },
  { name: "Children's Day", md: '11-14', occ: 'school', note: 'Stationery kits & return gifts' },
  { name: 'Christmas', md: '12-25', occ: 'festival', note: 'Gift boxes & mugs' },
  { name: 'New Year', md: '01-01', occ: 'office', note: 'Diaries & desk calendars' },
  { name: 'Republic Day', md: '01-26', occ: 'govt', note: 'Badges & sweet boxes' },
  { name: "Women's Day", md: '03-08', occ: 'office', note: 'Team gift sets' },
  { name: 'Independence Day', md: '08-15', occ: 'govt', note: 'Badges & programmes' },
  { name: "Teachers' Day", md: '09-05', occ: 'school', note: 'Diary sets & mugs' }
];
function renderUpcoming() {
  const now = new Date(Date.now() + 5.5 * 3600e3);
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  const list = OCCASION_DATES.map(o => {
    let ts;
    if (o.dates) ts = o.dates.map(d => Date.parse(d + 'T00:00:00Z')).find(x => x >= today);
    else { const [m, d] = o.md.split('-').map(Number); ts = Date.UTC(now.getUTCFullYear(), m - 1, d); if (ts < today) ts = Date.UTC(now.getUTCFullYear() + 1, m - 1, d); }
    return ts ? { ...o, ts, days: Math.round((ts - today) / 864e5) } : null;
  }).filter(Boolean).sort((a, b) => a.ts - b.ts).slice(0, 6);
  const fmt = ts => new Date(ts).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' });
  $('upcoming').innerHTML = list.map((o, i) => `<button type="button" data-up="${o.occ}" class="press snap-start shrink-0 w-[210px] text-left rounded-3xl border-2 border-ink p-4 grid gap-2 ${i === 0 ? 'bg-coral text-white' : 'bg-card'}">
      <span class="font-mono text-xs uppercase tracking-wider ${i === 0 ? 'text-butter' : 'text-muted'}">${fmt(o.ts)}</span>
      <span class="font-display font-extrabold text-xl leading-tight">${o.name}</span>
      <span class="font-display font-extrabold text-4xl tnum leading-none">${o.days === 0 ? 'Today' : o.days}<span class="text-sm font-sans font-semibold"> ${o.days === 0 ? '' : o.days === 1 ? 'day left' : 'days left'}</span></span>
      <span class="text-sm ${i === 0 ? 'text-white/85' : 'text-muted'}">${o.note}</span>
    </button>`).join('');
}
$('upcoming').addEventListener('click', e => { const b = e.target.closest('[data-up]'); if (!b) return; state.occ = b.dataset.up; if (BUDGETS.indexOf(state.budget) < 0) state.budget = 499; update(); $('builder').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' }); });

