// countdown to the IST cut-off
function tick() {
  const nowIst = new Date(Date.now() + 5.5 * 3600e3);
  const cut = new Date(Date.UTC(nowIst.getUTCFullYear(), nowIst.getUTCMonth(), nowIst.getUTCDate(), CUTOFF_HOUR_IST));
  let after = false;
  if (nowIst >= cut) { cut.setUTCDate(cut.getUTCDate() + 1); after = true; }
  const s = Math.max(0, Math.floor((cut - nowIst) / 1000));
  const pad = n => String(n).padStart(2, '0');
  $('countdown').textContent = `${pad(Math.floor(s / 3600))}:${pad(Math.floor(s % 3600 / 60))}:${pad(s % 60)}`;
  $('cutLabel').textContent = after ? "Today's slot is closed. Order in" : 'Order in';
  $('cutTail').textContent = after ? 'to get it the day after tomorrow by 11 AM · Delhi NCR' : 'to get it tomorrow by 11 AM · Delhi NCR';
}

